/* Cash keeps the existing money field, so older characters retain their balance. */
function setWalletBalance(key,value){if(!['money','bank'].includes(key)||!Number.isFinite(value)||value<0||value>Number.MAX_SAFE_INTEGER)throw Error('Сумма должна быть неотрицательным числом.');state.info[key]=value;}
function renderWallet(){return `<div class="character-wallet" aria-label="Деньги персонажа"><label>Наличные<input data-wallet="money" aria-label="Наличные" type="number" min="0" step="any" inputmode="decimal" value="${state.info.money}"></label><label>Банк<input data-wallet="bank" aria-label="Банк" type="number" min="0" step="any" inputmode="decimal" value="${state.info.bank??0}"></label></div>`;}
const beforeWalletHeader=renderHeader;
renderHeader=function(){beforeWalletHeader();const current=document.querySelector('.character-wallet');if(current)current.outerHTML=renderWallet();else document.querySelector('.level-button')?.insertAdjacentHTML('beforebegin',renderWallet());};
document.addEventListener('change',event=>{const key=event.target.dataset.wallet||(['money','bank'].includes(event.target.dataset.info)?event.target.dataset.info:null);if(!key)return;event.stopImmediatePropagation();try{const raw=event.target.value.trim();if(!raw)throw Error('Укажите сумму.');setWalletBalance(key,Number(raw));save();document.querySelectorAll('[data-wallet="'+key+'"],[data-info="'+key+'"]').forEach(input=>input.value=state.info[key]);}catch(error){toast(error.message);event.target.value=state.info[key];}},true);
render();
document.addEventListener('input',event=>{const key=event.target.dataset.wallet;if(!key)return;const raw=event.target.value.trim(),value=Number(raw);if(raw&&Number.isFinite(value)&&value>=0&&value<=Number.MAX_SAFE_INTEGER){setWalletBalance(key,value);save();}},true);
